BYTE = ['U32.and({w}, 255)', 'U32.and(U32.shrn({w}, 8n), 255)', 'U32.and(U32.shrn({w}, 16n), 255)', 'U32.shrn({w}, 24n)']


def zb(r):
    """zb<r>: the bytes of chunk q past its first r are zero, from its words (whole words past ceil(r / 4) zero,
    the bytes of word r / 4 past r % 4 zero)"""
    a, b = divmod(r, 4)
    first_zero = a + (1 if b else 0)
    W = lambda j: f'MR.wd(W, Nat.add(O.e8(Nat.add(q, 0n)), {j}n))'
    ps = ['+W: List<&2, U32>', '+q: Nat']
    ps += [f'+hw{j}: {{{W(j)} == 0 : U32}}' for j in range(first_zero, 8)]
    if b:
        ps += [f'+hb{k}: {{{BYTE[k].format(w=W(a))} == 0 : U32}}' for k in range(b, 4)]
    cur = [BYTE[p % 4].format(w=W(p // 4)) for p in range(32)]
    lines = []
    for p in range(r, 32):
        j, k = divmod(p, 4)
        motive = ', '.join('_' if i == p else cur[i] for i in range(32))
        P = f'{{WS.bdrop({r}n, [{motive}]) == SP.zero_bytes(Nat.sub(32n, {r}n)) : +List<U32>}}'
        if j >= first_zero:
            z = BYTE[k].format(w='0')
            e = f'Equal.cong(U32, U32, z => {BYTE[k].format(w="z")}, {W(j)}, 0, hw{j})'
            lines.append(f'  %Equal.sym(U32, {cur[p]}, {z}, {e}) :\n    {P}')
            cur[p] = z
        else:
            lines.append(f'  %Equal.sym(U32, {cur[p]}, 0, hb{k}) :\n    {P}')
            cur[p] = '0'
    return (f'def zb{r}(' + ', '.join(ps) + f')\n    -> {{WS.bdrop({r}n, WS.cb(W, Nat.add(q, 0n))) == SP.zero_bytes(Nat.sub(32n, {r}n)) : +List<U32>}}:\n'
            + '\n'.join(lines) + '\n  {==}\n')

